'use strict';
state.contributionMode=state.contributionMode==='ask'?'ask':'answer';state.answerTopics=state.answerTopics||[];state.roundSupports=state.roundSupports||[];state.questionUps=state.questionUps||[];
let includeAnswered=false;
// Fixtures are a clearly labeled SAMPLE ROUND, never real member rankings.
const sampleCandidates=[{id:'crew01',name:'Marco D.',rank:'Second Engineer',dept:'Engine',points:140,votes:22,answers:17,helpful:28},{id:'crew02',name:'Anne S.',rank:'Chief Officer',dept:'Deck',points:128,votes:24,answers:14,helpful:26},{id:'crew03',name:'Ramon C.',rank:'Marine Engineer',dept:'Engine',points:119,votes:16,answers:12,helpful:24},{id:'crew04',name:'Iris M.',rank:'ETO',dept:'Electrical',points:106,votes:18,answers:11,helpful:23},{id:'crew05',name:'Paolo R.',rank:'Oiler',dept:'Engine',points:98,votes:15,answers:10,helpful:20},{id:'crew06',name:'Bea L.',rank:'Third Officer',dept:'Deck',points:91,votes:13,answers:9,helpful:19},{id:'crew07',name:'Luis T.',rank:'Second Officer',dept:'Deck',points:85,votes:10,answers:8,helpful:18},{id:'crew08',name:'Nico F.',rank:'Fourth Engineer',dept:'Engine',points:79,votes:12,answers:8,helpful:16},{id:'crew09',name:'Ella P.',rank:'Engine Cadet',dept:'Engine',points:73,votes:9,answers:7,helpful:15},{id:'crew10',name:'Dan B.',rank:'Bosun',dept:'Deck',points:65,votes:7,answers:6,helpful:13},{id:'crew11',name:'Sam W.',rank:'Deck Cadet',dept:'Deck',points:54,votes:300,answers:5,helpful:10},{id:'crew12',name:'Alex J.',rank:'Motorman',dept:'Engine',points:49,votes:500,answers:4,helpful:9}];
function qualifyContributors(candidates){return [...candidates].sort((a,b)=>b.points-a.points||a.id.localeCompare(b.id)).slice(0,10)}
function rankedContributors(candidates=sampleCandidates,supports=state.roundSupports){return qualifyContributors(candidates).map(c=>({...c,totalVotes:c.votes+(supports.includes(c.id)?1:0)})).sort((a,b)=>b.totalVotes-a.totalVotes||b.points-a.points||a.id.localeCompare(b.id))}
function toggleProfileSupport(id,voter='local-user'){if(id===voter||!qualifyContributors(sampleCandidates).some(c=>c.id===id))return false;const old=[...state.roundSupports];state.roundSupports=state.roundSupports.includes(id)?state.roundSupports.filter(x=>x!==id):[...state.roundSupports,id];if(!persist()){state.roundSupports=old;return false}return true}
function localContributionPoints(){let score=0;for(const q of all()){if(own(q))score+=Number(q.receivedUps||0);else for(const a of q.answers.filter(ownAnswer))score+=Number(a.help||0)*2+(q.accepted===a.id?5:0)}return score}
const renderBeforeContribute=render,navBeforeContribute=nav,detailBeforeContribute=detail,navRenderBeforeContribute=renderNav;
renderNav=function(){navRenderBeforeContribute();const items=[['home','ask','Contribute'],['progress','explore','Progress'],['profile','profile','Profile']];for(const id of ['desktopNav','mobileNav'])document.getElementById(id).innerHTML=items.map(([p,i,label])=>`<button data-nav="${p}" class="${page===p||p==='progress'&&page==='leaderboard'?'active':''}">${icon(i)}<span>${label}</span></button>`).join('');const top=document.querySelector('.topbar');if(!document.querySelector('#globalSearch'))top.insertAdjacentHTML('beforeend',`<button class="global-search-button" id="globalSearch" data-global-search="true" aria-label="Search the question library">${icon('search')}<span>Search answers</span></button>`)};
function matchingQuestions(text){const normalize=s=>s.toLowerCase().replace(/\bfwg\b/g,'fresh water generator');const words=normalize(text).split(/\s+/).filter(Boolean);return words.length?all().filter(q=>words.every(w=>normalize(q.title+' '+q.body+' '+q.equipment+' '+q.tags.join(' ')+' '+q.answers.map(a=>a.text).join(' ')).includes(w))):[]}
function contributionView(){const mode=state.contributionMode;app.innerHTML=`<div class="task-hero"><div class="eyebrow">EXPERIENCE SHARED. KNOWLEDGE KEPT.</div><h1>${mode==='answer'?'Who can you help today?':'What would you like to ask?'}</h1><p>${mode==='answer'?'Choose your topics, then share experience where the crew needs it.':'Search first. Someone may have already faced the same situation.'}</p></div><div class="mode-switch" role="group" aria-label="Contribution task"><button data-contribution-mode="answer" class="${mode==='answer'?'active':''}" aria-pressed="${mode==='answer'}">↗ Answer</button><button data-contribution-mode="ask" class="${mode==='ask'?'active':''}" aria-pressed="${mode==='ask'}">＋ Ask</button></div>${mode==='answer'?answerTask():`<section class="card ask-path"><h2>Find a previous answer.</h2><form id="contributionSearch" class="search">${icon('search')}<input required type="search" name="question" placeholder="Equipment, symptoms, or your question…" aria-label="Find a previous question"><button class="qa-link">Search</button></form><div id="contributionMatches"></div><p>Still need to ask? Add the equipment, observations, and photos to give the crew useful context.</p><button class="btn" data-nav="ask">Continue with a new question →</button></section>`}<p class="qa-support">Local prototype. Questions and photos do not reach other devices yet. Follow vessel procedures, equipment manuals, and responsible officers.</p>`;if(mode==='ask'){const form=document.querySelector('#contributionSearch');form.oninput=()=>{const text=form.elements.namedItem('question').value.trim();const found=matchingQuestions(text).slice(0,3);document.querySelector('#contributionMatches').innerHTML=text.length<3?'':found.length?'<p class="hint">Related discussions</p>'+found.map(q=>`<div class="suggested-match"><button class="qa-link" data-open="${q.id}">${esc(q.title)} →</button></div>`).join(''):'<p class="hint">No matching question yet. You can continue below.</p>'};form.onsubmit=e=>{e.preventDefault();openSharedSearch(new FormData(form).get('question'))}}}
function answerTask(){const picked=state.answerTopics;const questions=all().filter(q=>picked.includes(q.equipment)&&q.status!=='Resolved'&&(includeAnswered||!q.answers.length));return `<details class="topic-picker" ${picked.length?'':'open'}><summary>${picked.length?'Change topics ('+picked.length+')':'Choose the topics you want to answer'}</summary>${Object.entries(topicsByDepartment).map(([d,topics])=>`<h3>${d}</h3><div class="topic-pick">${topics.map(t=>`<button class="${picked.includes(t)?'active':''}" data-answer-topic="${esc(t)}" aria-pressed="${picked.includes(t)}">${picked.includes(t)?'✓ ':''}${esc(t)}<span>${all().filter(q=>q.equipment===t&&q.status!=='Resolved').length}</span></button>`).join('')}</div>`).join('')}</details>${picked.length?`<div class="chips">${picked.map(t=>`<button class="chip active" data-answer-topic="${esc(t)}">${esc(t)} ×</button>`).join('')}</div><div class="task-options"><span>${questions.length} relevant discussion${questions.length===1?'':'s'}</span><label><input type="checkbox" id="includeAnswered" ${includeAnswered?'checked':''}>Include open questions with answers</label></div>${questions.map(card).join('')||'<div class="empty">No unanswered questions in these topics.<p>Include open discussions or choose another topic.</p></div>'}`:'<div class="empty">Your question queue starts with a topic.<p>Choose above, or switch to Ask.</p></div>'}`}
function openSharedSearch(text=''){page='learn';query=String(text||'').trim();topic='All topics';qaDepartment='All departments';qaView='all';sort='recent';render();window.scrollTo(0,0)}
function progressView(){const m=activityMetrics();const badges=qaBadgeDefinitions.filter(b=>state.qaBadges[b.id]).sort((a,b)=>state.qaBadges[b.id].localeCompare(state.qaBadges[a.id]));const latest=badges[0];app.innerHTML=`<div class="qa-head"><div><div class="qa-greeting">YOUR CONTRIBUTION JOURNEY</div><h1>Small answers. Shared progress.</h1><p>Recognition for participating—not a measure of professional competence.</p></div></div><section class="qa-hero"><div class="hero-text"><div class="medal">${latest?.symbol||'⚓'}</div><div class="eyebrow">${latest?'LATEST MILESTONE':'YOUR NEXT MILESTONE'}</div><h2>${latest?.title||'Starter'}</h2><p>${latest?.rule||'Complete your seafarer profile to get started.'}</p><button class="btn gold" data-nav="badges">Your milestones so far →</button></div><img class="mascot" src="assets/seafarer-mascot.webp" width="500" height="465" alt="Bulletproof Seafarers mascot celebrating participation"></section><div class="qa-metrics">${[['asked',m.asked,'Questions asked'],['answered',m.answered,'Questions answered'],['outcomes',m.outcomes,'Outcomes recorded'],['saved',m.saved,'Saved discussions']].map(([v,n,label])=>`<button class="qa-metric" data-activity="${v}"><strong>${n}</strong><span>${label} →</span></button>`).join('')}</div><section class="card"><div class="section-heading"><h2>Your milestones</h2><span class="score-pill">${badges.length} / ${qaBadgeDefinitions.length} earned</span></div><div class="progress-track"><label>Participation journey<span>${Math.round(badges.length/qaBadgeDefinitions.length*100)}%</span></label><progress max="${qaBadgeDefinitions.length}" value="${badges.length}" aria-label="Participation milestones earned"></progress></div><p class="hint">Local prototype badges. Counts above link to the original discussions, rather than repeating them here.</p></section><div class="qa-grid"><section class="card"><h3 style="font-size:16px;margin-top:0">Your most-answered topics</h3>${m.topics.length?m.topics.map(([t,n])=>`<div class="topic-rank"><button class="qa-link" data-qa-topic="${esc(t)}">${esc(t)}</button><small>${n} distinct question${n===1?'':'s'}</small></div>`).join(''):'<p class="hint">Answer another seafarer’s question to start building your contribution history.</p>'}<button class="qa-link" data-nav="home" style="margin-top:18px">Find a question to answer →</button></section><section class="card"><h3 style="font-size:16px;margin-top:0">Contribution points</h3><strong style="font-size:32px">${localContributionPoints()}</strong><p class="hint">Local preview only. Live points require other members’ reactions and server verification.</p><details class="rank-motto"><summary>Starting point rules</summary><p>+1 when another member upvotes your question.<br>+2 when another member marks your answer helpful.<br>+5 when the asker accepts your answer on their question.</p><p>No points for self-votes or simply posting. Acceptance and votes do not prove technical correctness. Rules are provisional for testing.</p></details></section></div><div class="progress-heading"><h2>Top seafarers</h2><span class="rank-preview">SAMPLE ROUND</span></div><p class="rank-motto">Earn a place through contribution points. Community support orders the qualified Top 10.</p><div class="progress-links"><button data-nav="leaderboard">View the Top 10 →</button></div>`}
function rankCard(c,index){const supported=state.roundSupports.includes(c.id);return `<article class="rank-card ${index===0?'first':''}"><div class="rank-place">${index+1}</div><div class="rank-avatar">${esc(c.name.split(' ').map(n=>n[0]).join(''))}</div><div class="rank-info"><h3>${esc(c.name)} <span>DEMO</span></h3><p>${esc(c.rank)} · ${esc(c.dept)}</p><div class="rank-tags"><span class="rank-award">${index===0?'★ Community #1':'Top 10 contributor'}</span><span>${c.points} qualifying points</span></div><details><summary>Contribution summary</summary><p>${c.answers} questions answered · ${c.helpful} helpful reactions.<br>Fictional sample activity; job rank is self-reported and separate from leaderboard position.</p></details></div><button class="rank-vote ${supported?'active':''}" data-profile-support="${c.id}" aria-label="${supported?'Remove support for':'Upvote'} ${esc(c.name)}" aria-pressed="${supported}"><span>▲</span><strong>${c.totalVotes}</strong><span>${supported?'Supported':'Upvote'}</span></button></article>`}
function leaderboardView(){app.innerHTML=`<button class="back" data-nav="progress">← Progress</button><div class="qa-head"><div><div class="qa-greeting">CONTRIBUTION EARNS THE SPOT</div><h1>Top seafarers</h1><p>Recognizing the crew helping others learn.</p></div></div><div class="rank-round"><span>Fixed weekly shortlist · sample round</span><span class="rank-preview">10 FICTIONAL CONTRIBUTORS</span></div><details class="rank-explainer"><summary>How points and upvotes work</summary><ol><li>At the weekly cutoff, contribution points qualify the Top 10 for the next round.</li><li>Only these ten profiles can receive leaderboard upvotes during that round.</li><li>Upvotes determine their positions. Ties use qualifying points, then a stable profile ID.</li><li>One vote per account per eligible profile per round. Votes can be removed. Self-votes do not count.</li><li>At the next cutoff, points select a fresh shortlist. Old profile votes do not carry into the next round.</li></ol><p>This sample uses fictional points and votes. Your test votes stay in this browser. A live leaderboard requires verified accounts, server-controlled eligibility, vote uniqueness, and abuse review.</p></details><div class="ranking-list">${rankedContributors().map(rankCard).join('')}</div><p class="qa-support">“Top seafarers” recognizes community contributions, not superior technical competence, qualifications, or safe operating authority. Do not use popularity as approval of a repair.</p>`}
detail=function(){detailBeforeContribute();const q=all().find(q=>q.id===selected);if(!q)return;const detailCard=app.querySelector('.detail');const count=Number(q.receivedUps||0)+(state.questionUps.includes(q.id)?1:0);detailCard.insertAdjacentHTML('beforeend',`<div class="question-demand"><button class="btn quiet" data-question-up="${q.id}" ${own(q)?'disabled':''} aria-pressed="${state.questionUps.includes(q.id)}">↑ ${state.questionUps.includes(q.id)?'You have this question too':'I have this question too'} · ${count}</button><small>${own(q)?'You cannot upvote your own question.':'Shows demand—not technical correctness.'}</small></div>`);for(const [i,article]of [...app.querySelectorAll('.answers article')].entries()){if(q.answers[i]&&ownAnswer(q.answers[i])){const vote=article.querySelector('button[data-vote]');if(vote){vote.removeAttribute('data-vote');vote.disabled=true;vote.textContent='Your answer · no self-votes'}}}}
nav=function(p){if(!state.hubOnboardingCompleted){navBeforeContribute(p);return}if(p==='progress'||p==='leaderboard'){page=p;selected=null;render();window.scrollTo(0,0);return}if(p==='home'){page='home';selected=null;render();window.scrollTo(0,0);return}navBeforeContribute(p)};
render=function(){if(!state.hubOnboardingCompleted){renderBeforeContribute();return}applyTheme();document.body.classList.remove('intro-mode');app.classList.remove('setup-view');if(page==='home'||page==='progress'||page==='leaderboard'){renderNav();document.querySelector('#sectionName').textContent=page==='home'?'Contribute':page==='progress'?'Your progress':'Top seafarers';if(page==='home')contributionView();if(page==='progress')progressView();if(page==='leaderboard')leaderboardView();return}renderBeforeContribute()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.contributionMode){state.contributionMode=b.dataset.contributionMode;persist();render()}if(b.dataset.answerTopic){const t=b.dataset.answerTopic;const old=[...state.answerTopics];state.answerTopics=state.answerTopics.includes(t)?state.answerTopics.filter(x=>x!==t):[...state.answerTopics,t];if(!persist())state.answerTopics=old;render()}if(b.dataset.globalSearch){if(!state.hubOnboardingCompleted){nav('welcome');return}openSharedSearch()}if(b.dataset.profileSupport){if(toggleProfileSupport(b.dataset.profileSupport)){render();toast('Sample profile support updated in this browser.')}}if(b.dataset.questionUp){const q=all().find(q=>q.id===b.dataset.questionUp);if(!q||own(q))return;const id=q.id;const old=[...state.questionUps];state.questionUps=state.questionUps.includes(id)?state.questionUps.filter(x=>x!==id):[...state.questionUps,id];if(!persist())state.questionUps=old;render()}});
document.addEventListener('change',e=>{if(e.target.id==='includeAnswered'){includeAnswered=e.target.checked;render()}});
render();
